        lgx_runtime_get_version;
        lgx_runtime_check_compatibility;
        
        # Configuration API
        lgx_config_create;
        lgx_config_destroy;
        lgx_config_set_*;
        
        # Capability detection
        lgx_runtime_has_capability;
        lgx_runtime_query_capabilities;
