        lgx_runtime_get_performance_characteristics;
        lgx_runtime_get_performance_targets;
        lgx_runtime_assess_performance;
        lgx_performance_tier_to_string;
        
        # Memory management
        lgx_alloc;
        lgx_alloc_aligned;
        lgx_alloc_with_strategy;
        lgx_alloc_with_intent;
        lgx_alloc_with_intent_ex;
        lgx_alloc_validate_intent;
